+// resolveGenericJSTestTargets MUST perform the resolveGenericJSTestTargets operation.
+func resolveGenericJSTestTargets(args []string, cwd string, fallbackToAll bool) []string {
+	var targets []string
+	for _, arg := range args {
+		if arg == "--" || strings.HasPrefix(arg, "-") {
+			continue
+		}
+		targets = append(targets, arg)
+	}
+	if len(targets) > 0 {
+		rootDir := GetRootDir()
+		var result []string
+		for _, target := range targets {
+			absTarget := target
+			if !filepath.IsAbs(absTarget) {
+				absTarget = filepath.Join(cwd, absTarget)
+			}
+			info, err := os.Stat(absTarget)
+			if err != nil {
+				continue
+			}
+			if !info.IsDir() {
+				if isJSTestFile(info.Name()) {
+					relPath, _ := filepath.Rel(rootDir, absTarget)
+					if relPath != "" {
+						result = append(result, relPath)
+					} else {
+						result = append(result, absTarget)
+					}
+				}
+				continue
+			}
+			_ = filepath.Walk(absTarget, func(path string, fi os.FileInfo, err error) error {
+				if err != nil || fi.IsDir() {
+					return nil
+				}
+				if isJSTestFile(fi.Name()) {
+					relPath, _ := filepath.Rel(rootDir, path)
+					if relPath != "" {
+						result = append(result, relPath)
+					} else {
+						result = append(result, path)
+					}
+				}
+				return nil
+			})
+		}
+		if len(result) > 0 {
+			return result
+		}
+	}
+	if fallbackToAll {
+		return findJSTestFiles(cwd)
+	}
+	return nil
+}

