+// sameStringSet compares two string slices as sets while ignoring empty values and duplicates.
+// [🧰semiorepo⌨️cli💻main🔖types🔖cli🔖hooks🛠️samestringset](semiorepo://p/i/semio-repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/sameStringSet)
+// sameStringSet MUST perform the sameStringSet operation.
+func sameStringSet(left []string, right []string) bool {
+	leftSeen := map[string]bool{}
+	rightSeen := map[string]bool{}
+	for _, item := range left {
+		if item != "" {
+			leftSeen[item] = true
+		}
+	}
+	for _, item := range right {
+		if item != "" {
+			rightSeen[item] = true
+		}
+	}
+	if len(leftSeen) != len(rightSeen) {
+		return false
+	}
+	for item := range leftSeen {
+		if !rightSeen[item] {
+			return false
+		}
+	}
+	return true
+}
